tool_calls:
python -m unittest discover -v && python - <<'PY'
from src.allocation import allocate
cases = [(10, 3), (0, 1), (1, 2), (1, 0), (1, -1), (-1, 2)]
for args in cases:
    try:
        print(args, '=>', allocate(*args))
    except Exception as exc:
        print(args, '=>', type(exc).__name__, str(exc))
PY

